require_once __DIR__ . '/../../../config.php'; require_once __DIR__ . '/../../../db.php'; require_once __DIR__ . '/../../../includes/tie/bootstrap.php'; require_once __DIR__ . '/../../../includes/tie/Api.php';
$id=UthengaTieObservability::requestId();try{if($_SERVER['REQUEST_METHOD']!=='GET')throw UthengaTieErrors::validation(['method'=>'GET is required.']);UthengaTieApi::requireFeature('vendor_profiles');$user=UthengaTieApi::requireAuthenticatedUser();if(!in_array($user['role'],ADMIN_ROLES,true))throw UthengaTieErrors::authorization();$rows=dbQuery("SELECT p.id,p.profile_type,p.profile_name,p.vendor_id,p.configuration,p.created_at,p.updated_at,u.name AS vendor_name,u.email AS vendor_email FROM tie_vendor_service_profiles p LEFT JOIN users u ON u.id=p.vendor_id WHERE p.status='READY_FOR_REVIEW' ORDER BY p.updated_at ASC LIMIT 100");foreach($rows as &$row){$row['configuration']=json_decode((string)($row['configuration']??'{}'),true)?:[];}$row=null;UthengaTieApi::respond(['success'=>true,'request_id'=>$id,'reviews'=>$rows]);}catch(Throwable $e){UthengaTieApi::handleError($e,$id);}
